 static readonly Dictionary<string,FieldInfo> nativeMassFields=new Dictionary<string,FieldInfo>();
 static object NativeMass(Part p,string name){
  FieldInfo field;if(!nativeMassFields.TryGetValue(name,out field)){field=typeof(Part).GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);nativeMassFields[name]=field;}
  try{return field==null?null:field.GetValue(p);}catch{return null;}
 }
