 public void Mark(){if(Recording)disk.Add("events.csv",TelemetryCsv.Row(Planetarium.GetUniversalTime()-startUt,"MARK",Samples));}
 public void Stop(string reason){if(!Recording)return;Recording=false;disk.Add("events.csv",TelemetryCsv.Row(Planetarium.GetUniversalTime()-startUt,"STOP",reason));disk.Stop(reason);Status="Saved "+Samples+" samples";Debug.Log("[KDA Telemetry] Stopped "+Folder);}
 void FixedUpdate(){
  if(!Recording)return;
  if(disk.Error!=""){Stop("Writer error");Status="Log error: "+disk.Error;return;}
  if(!HighLogic.LoadedSceneIsFlight||Body==null||Body.vessel!=car||car!=FlightGlobals.ActiveVessel||car.packed||car.parts.Count!=partCount){Stop("Vessel/scene changed");return;}
  if(Time.timeScale==0)return;
  try{Sample();}catch(Exception e){Stop("Sampling error");Status="Log error: "+e.Message;Debug.LogError("[KDA Telemetry] "+e);}
 }
